function greet(name) {
  return `Hello, ${name}!`;
}
const add = function (a, b) {
  return a + b;
};
const multiply = (a, b) => a * b;
console.log(greet('John'));
console.log('sum:', add(5, 3));
console.log('product:', multiply(4, 5));

const fruits = ['apple', 'banana', 'orange'];
const doubled = fruits.map((item) => item.toUpperCase());
const hasApple = fruits.includes('apple');
const sum = [1, 2, 3].reduce((total, value) => total + value, 0);
console.log({ fruits, doubled, hasApple, sum });

const person = { name: 'John', age: 30, city: 'New York' };
const greeting = `Hello, I am ${person.name} from ${person.city}`;
const updated = { ...person, email: 'john@example.com' };
console.log(greeting, updated);

const elementState = { textContent: 'Original Heading', classes: [] };
const updateText = (state, text) => ({ ...state, textContent: text });
const addClass = (state, className) => ({
  ...state,
  classes: [...state.classes, className]
});
const newState = addClass(updateText(elementState, 'Updated Heading'), 'highlight');
console.log('state', newState);

class SimpleEventBus {
  constructor() {
    this.listeners = new Map();
  }
  subscribe(event, fn) {
    const listeners = this.listeners.get(event) || [];
    listeners.push(fn);
    this.listeners.set(event, listeners);
  }
  emit(event, payload) {
    (this.listeners.get(event) || []).forEach((fn) => fn(payload));
  }
}
const bus = new SimpleEventBus();
bus.subscribe('click', (payload) => console.log('handled click', payload));
bus.emit('click', { x: 20, y: 40 });

const fakeFetch = (value, delay = 100) =>
  new Promise((resolve) => setTimeout(() => resolve(value), delay));
fakeFetch('Data loaded').then((result) => console.log(result));
async function fetchData() {
  const data = await fakeFetch('Async payload');
  console.log('async data', data);
}
fetchData();
